@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @FilteredTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @TodoTasks.Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @InProgressTasks.Count</span>
        <span class="stat-item"><strong>Done:</strong> @DoneTasks.Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @OverdueTasks.Count</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchQuery" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-columns">
        @foreach (var column in _columns)
        {
            var tasks = GetTasksForColumn(column);
            <div class="board-column">
                <div class="column-header">
                    <h3>@column <span class="badge">@tasks.Count</span></h3>
                </div>
                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @if (GetColumnIndex(column) > 0)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTask(task, -1)">← Move Left</button>
                                }
                                @if (GetColumnIndex(column) < _columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTask(task, 1)">Move Right →</button>
                                }
                            </div>
                        </div>
                    }
                </div>

                @if (_addingToColumn == column)
                {
                    <div class="add-task-form">
                        <input type="text" class="form-control" placeholder="Title"
                               @bind="_newTitle" />
                        <input type="text" class="form-control" placeholder="Assignee"
                               @bind="_newAssignee" />
                        <select class="form-control" @bind="_newPriority">
                            <option value="High">High</option>
                            <option value="Medium">Medium</option>
                            <option value="Low">Low</option>
                        </select>
                        <input type="date" class="form-control" @bind="_newDueDate" />
                        <div class="form-buttons">
                            <button class="btn btn-sm btn-primary" @onclick="SaveNewTask">Save</button>
                            <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-sm btn-outline-primary add-task-btn"
                            @onclick="() => StartAdd(column)">+ Add Task</button>
                }
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = { "To Do", "In Progress", "Done" };
    private List<TaskItem> _tasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchQuery = string.Empty;

    // Add task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(_searchQuery)
        ? _tasks
        : _tasks.Where(t => t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => GetTasksForColumn("To Do");
    private List<TaskItem> InProgressTasks => GetTasksForColumn("In Progress");
    private List<TaskItem> DoneTasks => GetTasksForColumn("Done");
    private List<TaskItem> OverdueTasks => FilteredTasks.Where(t => t.DueDate < DateTime.Today && t.Status != "Done").ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetTasksForColumn(string status) =>
        FilteredTasks.Where(t => t.Status == status).ToList();

    private int GetColumnIndex(string column) => Array.IndexOf(_columns, column);

    private async Task MoveTask(TaskItem task, int direction)
    {
        var currentIndex = GetColumnIndex(task.Status);
        var newIndex = currentIndex + direction;
        if (newIndex < 0 || newIndex >= _columns.Length) return;

        var newStatus = _columns[newIndex];
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                _tasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd()
    {
        _addingToColumn = null;
    }

    private async Task SaveNewTask()
    {
        if (string.IsNullOrWhiteSpace(_newTitle) || _addingToColumn is null) return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // The created task comes back with default status; update to match the column
            if (created.Status != _addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn);
                created = created with { Status = _addingToColumn };
            }
            _tasks.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }
}

