arguments.file_text:
.stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat-item {
    font-size: 0.9rem;
}

.stat-overdue strong {
    color: #dc3545;
}

.search-bar {
    margin-bottom: 1rem;
    max-width: 400px;
}

.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 0.5rem;
    padding: 0.75rem;
    min-width: 250px;
}

.column-header h3 {
    font-size: 1rem;
    margin: 0 0 0.5rem 0;
}

.column-header .badge {
    background: #6c757d;
    color: #fff;
    border-radius: 10px;
    padding: 0.15rem 0.5rem;
    font-size: 0.75rem;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.4rem;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
}

.task-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.task-assignee {
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.25rem;
}

.task-due {
    font-size: 0.8rem;
    color: #495057;
    margin-top: 0.25rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.1rem 0.5rem;
    border-radius: 3px;
    font-size: 0.75rem;
    font-weight: 600;
    color: #fff;
}

.priority-high {
    background-color: #dc3545;
}

.priority-medium {
    background-color: #ffc107;
    color: #212529;
}

.priority-low {
    background-color: #28a745;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.25rem;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    padding: 0.5rem;
    background: #fff;
    border: 1px dashed #adb5bd;
    border-radius: 0.4rem;
}

.add-task-form .form-control {
    font-size: 0.85rem;
    padding: 0.3rem 0.5rem;
}

.form-buttons {
    display: flex;
    gap: 0.5rem;
}

.add-task-btn {
    width: 100%;
    margin-top: 0.5rem;
}

.stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

